// Polyfill worker_threads.markAsUncloneable for Node.js < 21 compatibility (specifically Node 20.20.2)
import worker_threads from "node:worker_threads";
import { WebSocket } from "ws";

if (worker_threads && !worker_threads.markAsUncloneable) {
  (worker_threads as any).markAsUncloneable = function (obj: any) {
    if (worker_threads.markAsUntransferable) {
      try {
        worker_threads.markAsUntransferable(obj);
      } catch {
        // no-op
      }
    }
  };
}

// Polyfill Promise.withResolvers for Node.js < 22 compatibility (specifically Node 20.20.2)
if (typeof Promise.withResolvers === "undefined") {
  Promise.withResolvers = function <T>() {
    let resolve!: (value: T | PromiseLike<T>) => void;
    let reject!: (reason?: any) => void;
    const promise = new Promise<T>((res, rej) => {
      resolve = res;
      reject = rej;
    });
    return { promise, resolve, reject };
  } as any;
}

// Polyfill WebSocket for Node.js < 22 compatibility (specifically Node 20.20.2)
if (typeof globalThis.WebSocket === "undefined") {
  (globalThis as any).WebSocket = WebSocket;
}

// Test-only DATA_DIR isolation.
//
// Loaded via `node --import ./tests/_setup/isolateDataDir.ts` from the test/mutation
// invocations (package.json test scripts, stryker.conf.json tap.nodeArgs, the
// quality.yml TIA step, and the CI test jobs) — NEVER from production. It MUST stay
// out of open-sse/utils/setupPolyfill.ts, which is also imported by production
// (bin/omniroute.mjs, proxyFetch.ts, proxyDispatcher.ts) where redirecting DATA_DIR
// would point the live SQLite DB at a throwaway temp dir.
//
// Why: node:test spawns a process per test file and Stryker spawns one per sandbox,
// but every process resolves DATA_DIR to the SAME default (~/.omniroute) when the env
// var is unset (see src/lib/dataPaths.ts::resolveDataDir). Concurrent processes then
// open the SAME on-disk storage.sqlite, causing cross-file state races: SQLite lock
// contention that hangs `test:unit` under high `--test-concurrency`, and the
// non-deterministic baseline that forced Stryker to `concurrency: 1`.
//
// Giving each process its own DATA_DIR under the OS temp dir removes the shared file,
// so concurrent test processes never collide. Tests that set DATA_DIR explicitly keep
// winning — this only fills in an isolated default when none was chosen.
import fs from "node:fs";
import os from "node:os";
import path from "node:path";

// File logger worker threads can outlive a test's temporary DATA_DIR cleanup and then
// raise ENOENT/ENOTEMPTY after the test has already passed. Keep the global test default
// console-only; tests that cover file logging explicitly set APP_LOG_TO_FILE themselves.
process.env.APP_LOG_TO_FILE ||= "false";

if (!process.env.DATA_DIR) {
  const dir = fs.mkdtempSync(path.join(os.tmpdir(), "omniroute-test-"));
  process.env.DATA_DIR = dir;

  // Best-effort cleanup so a long suite run does not leak hundreds of temp DBs.
  process.on("exit", () => {
    try {
      fs.rmSync(dir, { recursive: true, force: true });
    } catch {
      // ignore — the OS reaps its temp dir eventually.
    }
  });
}

// System-trust guard: the suite must NEVER mutate the OS trust store. On a
// persistent self-hosted runner the cert-flow integration test installed a fake
// 105-byte PEM into /usr/local/share/ca-certificates and update-ca-certificates
// baked it into the bundle, breaking ALL system TLS on the VM (2026-07-05).
// installCert/uninstallCert/installTproxyCa/uninstallTproxyCa no-op under this.
process.env.OMNIROUTE_SKIP_SYSTEM_TRUST = "1";

// DNS-write guard: the suite must NEVER mutate /etc/hosts. Tests that exercise
// the real MITM path call addDNSEntries(); this env var makes it a no-op.
process.env.OMNIROUTE_SKIP_DNS_WRITE = "1";

// Regression guard for #7226: API-only smoke/nightly workflows must build with
// OMNIROUTE_BUILD_BACKEND_ONLY=1 so `npm run build:cli`'s fallback full build
// (scripts/build/prepublish.ts -> build-next-isolated.mjs) skips the ~126-leaf-page
// dashboard UI graph these workflows never exercise. Without this env var, the
// "Build CLI bundle" step silently runs a full Next.js production build inline,
// which is the actual source of the multi-minute variance/timeouts reported in #7226.
//
// npm-publish.yml is intentionally excluded: its "Build CLI bundle (standalone app)"
// step legitimately ships the full dashboard UI in the published npm package.
import test from "node:test";
import assert from "node:assert/strict";
import fs from "node:fs";
import path from "node:path";
import * as yaml from "js-yaml";

interface WorkflowStep {
  name?: string;
  run?: string;
  env?: Record<string, string>;
  [key: string]: unknown;
}

interface WorkflowJob {
  steps: WorkflowStep[];
  [key: string]: unknown;
}

interface WorkflowDoc {
  jobs: Record<string, WorkflowJob>;
  [key: string]: unknown;
}

const WORKFLOWS_DIR = path.join(process.cwd(), ".github", "workflows");

function loadWorkflow(fileName: string): WorkflowDoc {
  const raw = fs.readFileSync(path.join(WORKFLOWS_DIR, fileName), "utf8");
  return yaml.load(raw) as WorkflowDoc;
}

function isBackendOnly(step: WorkflowStep): boolean {
  const env = step.env || {};
  return env.OMNIROUTE_BUILD_BACKEND_ONLY === "1" || env.OMNIROUTE_BUILD_PROFILE === "backend";
}

// jobName: null selector means "any job" — used when a file has exactly one
// "Build CLI bundle" step but we don't want to hardcode/duplicate the job key.
interface Target {
  file: string;
  jobName: string;
  stepName: string;
}

const TARGETS: Target[] = [
  { file: "dast-smoke.yml", jobName: "dast-smoke", stepName: "Build CLI bundle" },
  { file: "nightly-schemathesis.yml", jobName: "schemathesis", stepName: "Build CLI bundle" },
  { file: "nightly-resilience.yml", jobName: "k6-soak", stepName: "Build CLI bundle" },
  { file: "nightly-llm-security.yml", jobName: "promptfoo-guard", stepName: "Build CLI bundle" },
  { file: "nightly-llm-security.yml", jobName: "garak", stepName: "Build CLI bundle" },
];

for (const { file, jobName, stepName } of TARGETS) {
  test(`${file} :: ${jobName} '${stepName}' step sets OMNIROUTE_BUILD_BACKEND_ONLY=1 (skips dashboard UI build the API-only smoke job never exercises)`, () => {
    const doc = loadWorkflow(file);
    const job = doc.jobs[jobName];
    assert.ok(job, `${file} must have a '${jobName}' job`);
    const step = job.steps.find((s) => s.name === stepName);
    assert.ok(step, `${file}'s '${jobName}' job must have a '${stepName}' step`);
    assert.equal(
      isBackendOnly(step),
      true,
      `${file}'s '${jobName}' -> '${stepName}' step must set OMNIROUTE_BUILD_BACKEND_ONLY=1 or OMNIROUTE_BUILD_PROFILE=backend`
    );
  });
}

test("npm-publish.yml 'Build CLI bundle (standalone app)' step must NOT be backend-only (it legitimately ships the full dashboard UI)", () => {
  const doc = loadWorkflow("npm-publish.yml");
  const publishJob = Object.values(doc.jobs).find((job) =>
    job.steps.some((s) => s.name === "Build CLI bundle (standalone app)")
  );
  assert.ok(publishJob, "npm-publish.yml must have a job with a 'Build CLI bundle (standalone app)' step");
  const step = publishJob!.steps.find((s) => s.name === "Build CLI bundle (standalone app)")!;
  assert.equal(
    isBackendOnly(step),
    false,
    "npm-publish.yml's build step must ship the full dashboard UI, not the backend-only stub"
  );
});

const NOT_RESOLVED: unique symbol = Symbol('NOT_RESOLVED')
const MERGE_KEY: unique symbol = Symbol('MERGE_KEY')

type ScalarRepresent = (data: any) => string
type SequenceRepresent = (data: any) => ArrayLike<unknown>
type MappingRepresent = (data: any) => Map<unknown, unknown>

type IdentifyFn = (data: any) => boolean
type RepresentTagNameFn = (data: any) => string

interface ScalarTagDefinition<Result = unknown> {
  tagName: string
  nodeKind: 'scalar'
  implicit: boolean
  matchByTagPrefix: boolean
  // Set of `source.charAt(0)` keys for which `resolve` may succeed (a superset of
  // what it really matches). A key is either a single character or '' (empty
  // source). `null` means "no constraint, always try". Used by the composer to
  // dispatch implicit scalars by first character without running every resolver.
  implicitFirstChars: readonly string[] | null
  // `isExplicit` is true for an explicit tag (`!!tag`), false for implicit plain
  // scalar resolution.
  resolve: (source: string, isExplicit: boolean, tagName: string) => Result | typeof NOT_RESOLVED
  identify: IdentifyFn | null
  // A scalar's printed form is text, so `represent` always yields a string. The
  // factory supplies a `String(data)` default when a tag omits it.
  represent: ScalarRepresent
  representTagName: RepresentTagNameFn | null
}

interface SequenceTagDefinition<Carrier = unknown, Result = Carrier> {
  tagName: string
  nodeKind: 'sequence'
  implicit: false
  matchByTagPrefix: boolean
  create: (tagName: string) => Carrier
  addItem: (carrier: Carrier, item: unknown, index: number) => void | string
  finalize: (carrier: Carrier) => Result
  carrierIsResult: boolean
  identify: IdentifyFn | null
  represent: SequenceRepresent
  representTagName: RepresentTagNameFn | null
}

interface MappingTagDefinition<Carrier = unknown, Result = Carrier> {
  tagName: string
  nodeKind: 'mapping'
  implicit: false
  matchByTagPrefix: boolean
  create: (tagName: string) => Carrier
  // Writes a pair. Returns '' on success, a non-empty error message otherwise
  // (key does not fit the representation, value rejected, ...). Always a string
  // so the hot path never allocates an exception wrapper.
  addPair: (carrier: Carrier, key: unknown, value: unknown) => string
  // Read side, mirrors `Map` — defining a representation means defining how to
  // read it back. `has` is the hot dedup probe (membership without fetching the
  // value); `keys`/`get` are used only on the cold merge path (`<<`).
  has: (carrier: Carrier, key: unknown) => boolean
  keys: (result: Result) => Iterable<unknown>
  get: (result: Result, key: unknown) => unknown
  finalize: (carrier: Carrier) => Result
  carrierIsResult: boolean
  identify: IdentifyFn | null
  represent: MappingRepresent
  representTagName: RepresentTagNameFn | null
}

type TagDefinition =
  | ScalarTagDefinition<any>
  | SequenceTagDefinition<any, any>
  | MappingTagDefinition<any, any>

interface ScalarTagOptions<Result> {
  implicit?: boolean
  matchByTagPrefix?: boolean
  implicitFirstChars?: readonly string[] | null
  resolve: ScalarTagDefinition<Result>['resolve']
  identify?: ScalarTagDefinition<Result>['identify']
  represent?: ScalarTagDefinition<Result>['represent']
  representTagName?: ScalarTagDefinition<Result>['representTagName']
}

type RepresentOptions<Container, Canonical, Represent> =
  | {
      identify?: null
      represent?: Represent
      representTagName?: RepresentTagNameFn | null
    }
  | (Container extends Canonical
      ? {
          identify?: IdentifyFn | null
          represent?: Represent
          representTagName?: RepresentTagNameFn | null
        }
      : {
          identify: IdentifyFn
          represent: Represent
          representTagName?: RepresentTagNameFn | null
        })

type SequenceTagOptions<Carrier, Result = Carrier> = {
  matchByTagPrefix?: boolean
  create: SequenceTagDefinition<Carrier, Result>['create']
  addItem: SequenceTagDefinition<Carrier, Result>['addItem']
  finalize?: SequenceTagDefinition<Carrier, Result>['finalize']
} & RepresentOptions<Result, ArrayLike<unknown>, SequenceRepresent>

type MappingTagOptions<Carrier, Result = Carrier> = {
  matchByTagPrefix?: boolean
  create: MappingTagDefinition<Carrier, Result>['create']
  addPair: MappingTagDefinition<Carrier, Result>['addPair']
  has: MappingTagDefinition<Carrier, Result>['has']
  keys: MappingTagDefinition<Carrier, Result>['keys']
  get: MappingTagDefinition<Carrier, Result>['get']
  finalize?: MappingTagDefinition<Carrier, Result>['finalize']
} & RepresentOptions<Result, Map<unknown, unknown>, MappingRepresent>

function defineScalarTag<Result> (tagName: string, options: ScalarTagOptions<Result>): ScalarTagDefinition<Result> {
  return {
    tagName,
    nodeKind: 'scalar',
    implicit: options.implicit ?? false,
    matchByTagPrefix: options.matchByTagPrefix ?? false,
    implicitFirstChars: options.implicitFirstChars ?? null,
    resolve: options.resolve,
    identify: options.identify ?? null,
    represent: options.represent ?? (data => String(data)),
    representTagName: options.representTagName ?? null
  }
}

function defineSequenceTag<Carrier, Result = Carrier> (tagName: string, options: SequenceTagOptions<Carrier, Result>): SequenceTagDefinition<Carrier, Result> {
  const carrierIsResult = options.finalize === undefined

  return {
    tagName,
    nodeKind: 'sequence',
    implicit: false,
    matchByTagPrefix: options.matchByTagPrefix ?? false,
    create: options.create,
    addItem: options.addItem,
    finalize: options.finalize ?? (carrier => carrier as unknown as Result),
    carrierIsResult,
    identify: options.identify ?? null,
    represent: options.represent ?? (data => data as ArrayLike<unknown>),
    representTagName: options.representTagName ?? null
  }
}

function defineMappingTag<Carrier, Result = Carrier> (tagName: string, options: MappingTagOptions<Carrier, Result>): MappingTagDefinition<Carrier, Result> {
  const carrierIsResult = options.finalize === undefined

  return {
    tagName,
    nodeKind: 'mapping',
    implicit: false,
    matchByTagPrefix: options.matchByTagPrefix ?? false,
    create: options.create,
    addPair: options.addPair,
    has: options.has,
    keys: options.keys,
    get: options.get,
    finalize: options.finalize ?? (carrier => carrier as unknown as Result),
    carrierIsResult,
    identify: options.identify ?? null,
    represent: options.represent ?? (data => data as Map<unknown, unknown>),
    representTagName: options.representTagName ?? null
  }
}

export {
  NOT_RESOLVED,
  MERGE_KEY,
  defineScalarTag,
  defineSequenceTag,
  defineMappingTag,

  type ScalarTagDefinition,
  type SequenceTagDefinition,
  type MappingTagDefinition,
  type TagDefinition,
  type ScalarTagOptions,
  type SequenceTagOptions,
  type MappingTagOptions,
  type ScalarRepresent,
  type SequenceRepresent,
  type MappingRepresent
}
import { defineScalarTag } from '../../tag.ts'

const strTag = defineScalarTag('tag:yaml.org,2002:str', {
  resolve: (source) => source,
  identify: (data) => typeof data === 'string'
})

export { strTag }
import { defineScalarTag, NOT_RESOLVED } from '../../tag.ts'

const NULL_VALUES = ['', '~', 'null', 'Null', 'NULL']

const nullCoreTag = defineScalarTag('tag:yaml.org,2002:null', {
  implicit: true,
  // Superset of source.charAt(0) over all matched inputs: '' (empty), '~', 'null'/'Null'/'NULL'.
  implicitFirstChars: ['', '~', 'n', 'N'],
  resolve: (source) => {
    if (NULL_VALUES.indexOf(source) !== -1) return null

    return NOT_RESOLVED
  },
  identify: (object) => object === null,
  represent: () => 'null'
})

export { nullCoreTag }
import { defineScalarTag, NOT_RESOLVED } from '../../tag.ts'

const nullJsonTag = defineScalarTag('tag:yaml.org,2002:null', {
  implicit: true,
  // Superset of source.charAt(0) over all matched inputs: null.
  implicitFirstChars: ['n'],
  resolve: (source, isExplicit) => {
    if (source === 'null' || (isExplicit && source === '')) return null

    return NOT_RESOLVED
  },
  identify: (object) => object === null,
  represent: () => 'null'
})

export { nullJsonTag }
import { defineScalarTag, NOT_RESOLVED } from '../../tag.ts'

const NULL_VALUES = ['', '~', 'null', 'Null', 'NULL']

const nullYaml11Tag = defineScalarTag('tag:yaml.org,2002:null', {
  implicit: true,
  // Superset of source.charAt(0) over all matched inputs: '' (empty), '~', 'null'/'Null'/'NULL'.
  implicitFirstChars: ['', '~', 'n', 'N'],
  resolve: (source) => {
    if (NULL_VALUES.indexOf(source) !== -1) return null

    return NOT_RESOLVED
  },
  identify: (object) => object === null,
  represent: () => 'null'
})

export { nullYaml11Tag }
import { defineScalarTag, NOT_RESOLVED } from '../../tag.ts'

const TRUE_VALUES = ['true', 'True', 'TRUE']
const FALSE_VALUES = ['false', 'False', 'FALSE']

const boolCoreTag = defineScalarTag('tag:yaml.org,2002:bool', {
  implicit: true,
  // Superset of source.charAt(0) over all matched inputs: true/True/TRUE, false/False/FALSE.
  implicitFirstChars: ['t', 'T', 'f', 'F'],
  resolve: (source) => {
    if (TRUE_VALUES.indexOf(source) !== -1) return true
    if (FALSE_VALUES.indexOf(source) !== -1) return false

    return NOT_RESOLVED
  },
  identify: (object) => Object.prototype.toString.call(object) === '[object Boolean]',
  represent: (object) => object ? 'true' : 'false'
})

export { boolCoreTag }
import { defineScalarTag, NOT_RESOLVED } from '../../tag.ts'

const TRUE_VALUES = ['true']
const FALSE_VALUES = ['false']

const boolJsonTag = defineScalarTag('tag:yaml.org,2002:bool', {
  implicit: true,
  // Superset of source.charAt(0) over all matched inputs: true, false.
  implicitFirstChars: ['t', 'f'],
  resolve: (source) => {
    if (TRUE_VALUES.indexOf(source) !== -1) return true
    if (FALSE_VALUES.indexOf(source) !== -1) return false

    return NOT_RESOLVED
  },
  identify: (object) => Object.prototype.toString.call(object) === '[object Boolean]',
  represent: (object) => object ? 'true' : 'false'
})

